SELECT COUNT(*) FROM "Equipment" e 
JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
WHERE (et.type_indices->>'safety_idx')::real > 70;

SELECT COUNT(*) FROM "Equipment" e 
JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
WHERE (et.type_indices->>'safety_idx')::real > 10;

SELECT COUNT(*) FROM "Equipment" e 
LEFT JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
WHERE et."EquipType" IS NOT NULL;
